import sys

data = sys.stdin.read().split()
n0 = int(data[0])
m = n0
ph = list(range(m + 1))
for p in range(2, m + 1):
    if ph[p] == p:
        for j in range(p, m + 1, p):
            ph[j] -= ph[j] // p
print(sum(ph[1:]))

